/** 
 * Print out received errors for debugging purposes and may be for expected errors that can be acted upon.
 * @param msg the error message
 */
@Override public void onError(ErrorMessage msg){
  try {
    if (LOGGER.isDebugEnabled()) {
      LOGGER.debug("ERROR: " + msg.getSource() + ": "+ msg.getText());
    }
  } catch (NullPointerException e) {
    // Ignore or log separately; msg is null
  }
  if (IrcStack.this.connectionState != null) {
    if (!IrcStack.this.connectionState.isConnected()) {
      IrcStack.this.provider.setCurrentRegistrationState(RegistrationState.CONNECTION_FAILED);
    }
  }
}
